import { PhotoMemClient } from 'photomem';

const client = new PhotoMemClient({ authToken: 'your_clerk_token' });

// Poll for completion
const pollExport = async () => {
  const status = await client.analytics.getExportStatus({
    orgId: 'org_abc123def456',
    exportId: 'exp_abc123def456'
  });

  if (status.status === 'completed') {
    console.log(`Download: ${status.downloadUrl}`);
    return status;
  }

  await new Promise(resolve => setTimeout(resolve, 5000));
  return pollExport();
};

